"""Regenerate binary64_golden.h using integer arithmetic only (no float/parser).

The decimal text is an exact rational N/D. Choose its binary exponent, round
the scaled integer quotient to nearest, ties to even, then encode IEEE fields.
Python is needed only for regeneration, never for building/running C++ tests.
"""
from pathlib import Path
from fractions import Fraction
import re


def rational(text):
    match = re.fullmatch(r'([+-]?)(\d*)(?:\.(\d*))?(?:[eE]([+-]?\d+))?', text)
    sign, whole, fraction, exponent = match.groups()
    fraction = fraction or ''
    n = int(whole + fraction)
    # Exact zeros do not require constructing an enormous power of ten.
    if not n:
        return sign == '-', Fraction(0)
    scale = int(exponent or '0') - len(fraction)
    return sign == '-', Fraction(n * 10 ** max(0, scale), 10 ** max(0, -scale))


def round_even(n, d):
    q, r = divmod(n, d)
    return q + (2 * r > d or (2 * r == d and q % 2 == 1))


def binary64(text):
    negative, value = rational(text)
    sign = int(negative) << 63
    if not value:
        return sign
    n, d = value.numerator, value.denominator
    e = n.bit_length() - d.bit_length()
    below_power = n < d << e if e >= 0 else n << -e < d
    if below_power:
        e -= 1
    shift = 52 - max(e, -1022)
    m = round_even(n << max(0, shift), d << max(0, -shift))
    if m == 1 << 53:
        m >>= 1
        e += 1
    if not m or e > 1023:
        raise ValueError('out of supported range')
    if e < -1022 and m < 1 << 52:
        return sign | m
    return sign | ((max(e, -1022) + 1023) << 52) | (m - (1 << 52))


def exact_dyadic(n, power):
    # Exact n / 2**power decimal, including all trailing significant digits.
    digits = str(n * 5 ** power).zfill(power + 1)
    return digits[:-power] + '.' + digits[-power:]


tokens = [
    '0', '+0', '-0', '-0.000e+99999999999999999999999999999999999',
    '+0e-99999999999999999999999999999999999',
    '1', '-1', '+1', '.5', '-.5', '1.', '+1.5E+4', '1.25e-3',
    '123.123456', '-123.123456789', '0.123456789012', '-0.123456789012345',
    '123456789012345.125', '-0.000000000000001', '0.1',
    '1.0000000000000002', '1.0000000000000004',
    exact_dyadic((1 << 53) + 1, 53),  # midpoint: even lower
    exact_dyadic((1 << 53) + 3, 53),  # midpoint: even upper
    '1.7976931348623157e308', '-1.7976931348623157e308',
    '2.2250738585072014e-308', '-2.2250738585072014e-308', '2.225073858507201e-308',
    '4.9406564584124654e-324', '-4.9406564584124654e-324',
    '9.8813129168249309e-324', '2.4703282292062328e-324',
    exact_dyadic(1, 1074),  # exact minimum subnormal
    exact_dyadic((1 << 53) - 1, 1075),  # midpoint at normal/subnormal boundary
    exact_dyadic(3, 1075),  # subnormal midpoint, round to even 2
    str(((1 << 54) - 1) * (1 << 970) - 1),  # immediately below overflow rounding midpoint
]

lines = ['// Generated by generate_binary64_golden.py with exact integer/rational arithmetic.',
         '#pragma once', '#include <array>', '#include <cstdint>', 'namespace asc_test {',
         'struct Golden { const char *token; std::uint64_t bits; };',
         f'inline constexpr std::array<Golden, {len(tokens)}> golden{{{{']
for token in tokens:
    lines.append(f'    {{"{token}", 0x{binary64(token):016x}ULL}},')
lines += ['}};']
rejected = [exact_dyadic(1, 1075), str(((1 << 54) - 1) * (1 << 970))]
for token in rejected:
    try:
        binary64(token)
    except ValueError:
        pass
    else:
        raise AssertionError('Expected unrepresentable golden')
lines += [f'inline constexpr std::array<const char *, {len(rejected)}> rangeErrors{{{{']
lines += [f'    "{token}",' for token in rejected]
lines += ['}};', '} // namespace asc_test', '']
Path(__file__).with_name('binary64_golden.h').write_bytes('\n'.join(lines).encode('utf-8'))
